import{at as e,it as t,n,vt as r}from"./chunks/framework.B6nQ8gjX.js";var i=JSON.parse(`{"title":"Extra Parameters","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/extra-params.md","filePath":"en/guide/extra-params.md"}`),a={name:`en/guide/extra-params.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="extra-parameters" tabindex="-1">Extra Parameters <a class="header-anchor" href="#extra-parameters" aria-label="Permalink to “Extra Parameters”">​</a></h1><p>This page describes Zotero PDF2zh <strong>v4.1.7</strong> (including earlier features).</p><p>This page documents service-specific options used by <code>pdf2zh_next</code> and legacy <code>pdf2zh</code> where noted. Extra parameter names must match the corresponding configuration fields.</p><div class="tip custom-block"><p class="custom-block-title">Plugin behavior</p><p>The Zotero LLM API editor stores values in <strong>Extra Parameters</strong> / <code>extraData</code>. Opening the editor lists the extra fields supported for the current service. Click <strong>Add Parameter</strong> to pick from that list, or type a custom key. Leave a field unset to keep the upstream default. JSON mode is not enabled by default.</p></div><h2 id="openai-openai-compatible" tabindex="-1">OpenAI / OpenAI-compatible <a class="header-anchor" href="#openai-openai-compatible" aria-label="Permalink to “OpenAI / OpenAI-compatible”">​</a></h2><h3 id="base-fields" tabindex="-1">Base fields <a class="header-anchor" href="#base-fields" aria-label="Permalink to “Base fields”">​</a></h3><ul><li><code>openai_model</code> / <code>openai_compatible_model</code></li><li><code>openai_base_url</code> / <code>openai_compatible_base_url</code></li><li><code>openai_api_key</code> / <code>openai_compatible_api_key</code></li></ul><h3 id="extra-fields" tabindex="-1">Extra fields <a class="header-anchor" href="#extra-fields" aria-label="Permalink to “Extra fields”">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><code>openai_timeout</code> / <code>openai_compatible_timeout</code></td><td>Request timeout in seconds</td><td><code>600</code></td></tr><tr><td><code>openai_temperature</code> / <code>openai_compatible_temperature</code></td><td>Sampling temperature</td><td><code>0.3</code></td></tr><tr><td><code>openai_send_temprature</code> / <code>openai_compatible_send_temperature</code></td><td>Whether to send temperature</td><td><code>true</code></td></tr><tr><td><code>openai_reasoning_effort</code> / <code>openai_compatible_reasoning_effort</code></td><td>Reasoning effort for supported models</td><td><code>low</code></td></tr><tr><td><code>openai_send_reasoning_effort</code> / <code>openai_compatible_send_reasoning_effort</code></td><td>Whether to send reasoning effort</td><td><code>true</code></td></tr><tr><td><code>openai_enable_json_mode</code> / <code>openai_compatible_enable_json_mode</code></td><td>Enable JSON mode; off by default</td><td><code>true</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">OpenAI compatibility spelling</p><p><code>pdf2zh_next</code> intentionally keeps the historical <code>openai_send_temprature</code> spelling for the native OpenAI service. The Server automatically migrates the old <code>openai_send_temperature</code> alias used by earlier plugin releases, while <code>openai_compatible_send_temperature</code> keeps the normal spelling.</p></div><h2 id="deepseek" tabindex="-1">DeepSeek <a class="header-anchor" href="#deepseek" aria-label="Permalink to “DeepSeek”">​</a></h2><p>DeepSeek V4 models, including <code>deepseek-v4-pro</code> and <code>deepseek-v4-flash</code>, support explicit thinking controls. Zotero PDF2zh keeps thinking <strong>disabled by default</strong> to avoid unexpected reasoning-token cost during PDF translation.</p><h3 id="base-fields-1" tabindex="-1">Base fields <a class="header-anchor" href="#base-fields-1" aria-label="Permalink to “Base fields”">​</a></h3><ul><li><code>deepseek_model</code></li><li><code>deepseek_api_key</code></li></ul><h3 id="extra-fields-1" tabindex="-1">Extra fields <a class="header-anchor" href="#extra-fields-1" aria-label="Permalink to “Extra fields”">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th><th>Values / default</th></tr></thead><tbody><tr><td><code>deepseek_thinking_mode</code></td><td>Enable DeepSeek V4 thinking</td><td><code>disabled</code> / <code>enabled</code>; default <code>disabled</code></td></tr><tr><td><code>deepseek_reasoning_effort</code></td><td>Thinking effort, used only when thinking is enabled</td><td><code>high</code> / <code>max</code>; default <code>high</code> when enabled</td></tr><tr><td><code>deepseek_enable_json_mode</code></td><td>Enable JSON mode</td><td>Depends on the <code>pdf2zh_next</code> configuration</td></tr></tbody></table><p>These values still travel through the plugin&#39;s existing <code>extraData</code> mechanism.</p><h3 id="how-the-setting-is-executed" tabindex="-1">How the setting is executed <a class="header-anchor" href="#how-the-setting-is-executed" aria-label="Permalink to “How the setting is executed”">​</a></h3><p><code>pdf2zh_next 2.9.0</code> added <code>deepseek_thinking_mode</code> and <code>deepseek_reasoning_effort</code>, corresponding to:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>deepseek_thinking_mode     -&gt; --deepseek-thinking-mode</span></span>
<span class="line"><span>deepseek_reasoning_effort  -&gt; --deepseek-reasoning-effort</span></span></code></pre></div><p>Zotero PDF2zh v4.1.0 applies this safety flow (unchanged in v4.1.1):</p><ol><li>the plugin stores the choice through <code>extraData</code>;</li><li>an omitted DeepSeek V4 choice is normalized to <code>disabled</code>;</li><li>for uv / conda / system Python, the Server checks the <strong>installed <code>pdf2zh_next</code> distribution metadata/source in the exact Python environment that will run</strong>, without launching the heavyweight CLI just for capability detection;</li><li>supported settings are converted to the official upstream CLI flags;</li><li>default no-thinking on an old runtime strips those fields and still translates;</li><li>user-enabled thinking on an unsupported runtime is stopped before any translation API call;</li><li>Windows standalone executables, which cannot be inspected through Python distribution metadata, use a separate executable capability check;</li><li>non-V4 DeepSeek models do not receive V4-only parameters.</li></ol><div class="warning custom-block"><p class="custom-block-title">Why not run <code>pdf2zh_next --help</code>?</p><p><code>pdf2zh_next 2.9.0</code> may import BabelDOC/high-level modules before CLI parsing, so even help output can be a heavyweight operation on some systems. v4.1.0 uses a static capability probe for normal Python environments to avoid misclassifying a successfully installed runtime as broken simply because help startup took too long.</p></div><div class="warning custom-block"><p class="custom-block-title">pdf2zh_next vs. BabelDOC versions</p><p>DeepSeek V4 thinking support is provided by the <strong><code>pdf2zh_next</code> runtime</strong>, not by the BabelDOC version. <code>pdf2zh_next 2.8.2</code> does not define these fields; 2.9.0 does. BabelDOC and PyMuPDF primarily affect PDF parsing and dependency compatibility.</p></div><p>Upstream CLI examples:</p><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Recommended default for PDF translation: thinking disabled</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pdf2zh_next</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> input.pdf</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --deepseek</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --deepseek-model</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deepseek-v4-flash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --deepseek-thinking-mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> disabled</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./output</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Thinking enabled with high effort</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pdf2zh_next</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> input.pdf</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --deepseek</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --deepseek-model</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deepseek-v4-pro</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --deepseek-thinking-mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enabled</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --deepseek-reasoning-effort</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> high</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./output</span></span></code></pre></div><h2 id="deeplx-legacy-pdf2zh-1-x" tabindex="-1">DeepLX (legacy pdf2zh 1.x) <a class="header-anchor" href="#deeplx-legacy-pdf2zh-1-x" aria-label="Permalink to “DeepLX (legacy pdf2zh 1.x)”">​</a></h2><p>DeepLX is configured through the legacy <code>pdf2zh</code> engine. In <code>pdf2zh</code> 1.x, the value of <code>DEEPLX_ACCESS_TOKEN</code> is optional, but the key itself must remain present. The current configuration mapping preserves this optional field.</p><ul><li><code>DEEPLX_ENDPOINT</code>: custom DeepLX endpoint; enter it as Base URL.</li><li><code>DEEPLX_ACCESS_TOKEN</code>: optional token; leave it empty if the endpoint does not require one.</li></ul><p>If logs show requests to <code>https://api.deepl.com/v2/translate</code>, first verify that the selected service is <code>deeplx</code> rather than <code>deepl</code>.</p><h2 id="ollama" tabindex="-1">Ollama <a class="header-anchor" href="#ollama" aria-label="Permalink to “Ollama”">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><code>num_predict</code></td><td>Maximum number of generated tokens</td><td><code>2000</code></td></tr></tbody></table><h2 id="azure-openai" tabindex="-1">Azure OpenAI <a class="header-anchor" href="#azure-openai" aria-label="Permalink to “Azure OpenAI”">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>azure_openai_api_version</code></td><td>Azure OpenAI API version</td></tr></tbody></table><h2 id="siliconflow" tabindex="-1">SiliconFlow <a class="header-anchor" href="#siliconflow" aria-label="Permalink to “SiliconFlow”">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>siliconflow_enable_thinking</code></td><td>Enable thinking when supported</td></tr><tr><td><code>siliconflow_send_enable_thinking_param</code></td><td>Whether to send the thinking parameter</td></tr><tr><td><code>siliconflow_enable_json_mode</code></td><td>Enable JSON mode; off by default</td></tr></tbody></table><h2 id="siliconflow-free" tabindex="-1">SiliconFlow Free <a class="header-anchor" href="#siliconflow-free" aria-label="Permalink to “SiliconFlow Free”">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>siliconflow_free_enable_json_mode</code></td><td>Enable JSON mode; off by default</td></tr></tbody></table><h2 id="qwen-mt" tabindex="-1">Qwen MT <a class="header-anchor" href="#qwen-mt" aria-label="Permalink to “Qwen MT”">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>ali_domains</code></td><td>Domain/context hint used by Qwen MT</td></tr></tbody></table><h2 id="general-notes" tabindex="-1">General Notes <a class="header-anchor" href="#general-notes" aria-label="Permalink to “General Notes”">​</a></h2><ul><li>Enter boolean values as <code>true</code> or <code>false</code>.</li><li>Leave optional values empty when you want the upstream default.</li><li>Service APIs and accepted model-specific parameters change over time; when a parameter is rejected, compare your installed <code>pdf2zh_next</code> version with the current upstream documentation.</li></ul><div class="info custom-block"><p class="custom-block-title">Related documentation</p><ul><li><a href="/en/guide/configuration.html">Configuration</a></li><li><a href="/en/guide/package-update.html">Translation Environment Updates</a></li><li><a href="/en/guide/faq/translation-service.html">Translation Service FAQ</a></li></ul></div>`,43)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};